codeExamples.code:
terraform {
  required_version = ">= 1.7"
  backend "s3" {
    bucket         = "acme-tf-state"
    key            = "dataops/eks.tfstate"
    region         = "us-east-1"
    dynamodb_table = "acme-tf-locks"   # state locking
  }
}

provider "aws" { region = var.region }

# --- EKS cluster + managed node group via the community module ---
module "eks" {
  source          = "terraform-aws-modules/eks/aws"
  version         = "~> 20.0"
  cluster_name    = "dataops-${var.env}"
  cluster_version = "1.30"
  vpc_id          = var.vpc_id
  subnet_ids      = var.private_subnet_ids

  eks_managed_node_groups = {
    pipelines = {
      instance_types = ["m6i.large"]
      min_size       = 2
      max_size       = 10          # cluster autoscaler headroom
      desired_size   = 3
    }
  }
}

# --- Data bucket for the pipeline ---
resource "aws_s3_bucket" "pipeline_data" {
  bucket = "acme-orders-pipeline-${var.env}"
}

resource "aws_s3_bucket_versioning" "pipeline_data" {
  bucket = aws_s3_bucket.pipeline_data.id
  versioning_configuration { status = "Enabled" }
}

# --- Least-privilege IAM role bound to the K8s SA via IRSA ---
module "pipeline_irsa" {
  source                        = "terraform-aws-modules/iam/aws//modules/iam-role-for-service-accounts-eks"
  role_name                     = "orders-pipeline-${var.env}"
  oidc_providers = {
    main = {
      provider_arn               = module.eks.oidc_provider_arn
      namespace_service_accounts = ["data:orders-pipeline"]
    }
  }
}

resource "aws_iam_role_policy" "bucket_access" {
  name = "bucket-access"
  role = module.pipeline_irsa.iam_role_name
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect   = "Allow",
      Action   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"],
      Resource = [aws_s3_bucket.pipeline_data.arn, "${aws_s3_bucket.pipeline_data.arn}/*"]
    }]
  })
}
